        }
        int trapped = 0, pockets = 0;
        for (int i = 0; i < solid.Length; i++) if (!solid[i] && !visited[i]) { pockets++; trapped += Flood(i, false); }
        Array.Clear(visited);
        int components = 0;
        for (int i = 0; i < solid.Length; i++) if (solid[i] && !visited[i]) { components++; Flood(i, true); }
