            Vector3 n = a.Length == 10 ? new(v[3], v[4], v[5]) : Vector3.Zero;
            float w = a.Length == 10 ? v[6] : 1;
            Vector3 sensor = a.Length == 10 ? new(v[7], v[8], v[9]) : Vector3.Zero;
