            float step = h / 2, length = 0;
            bool entered = false, exited = false;
            for (float t = step; t <= 2 * minWall; t += step)
            {
                bool inside = part.bIsInside(p - normal * t);
                if (inside) { entered = true; length = t; }
                else if (entered) { exited = true; break; }
                else if (t >= h) break;
            }
