                if (lateral.LengthSquared() > footprint * footprint || d < -mu) continue;
                float w = s.W * MathF.Max(0, 1 - lateral.Length() / footprint);
                if (w <= 0) continue;
                distance = (weight * distance + w * Math.Clamp(d, -mu, mu)) / (weight + w);
                weight += w;
