        for (int i = 0; i < solid.Length; i++)
        {
            var (x,y,z) = Decode(i);
            if (!solid[i] && !visited[i] && (x==0 || y==0 || z==0 || x==nx-1 || y==ny-1 || z==nz-1)) Flood(i, false);
        }
