            // Only a flat patch entirely on z=0 is plate contact, never an internal cavity floor.
            bool plate = MathF.Abs(a.Z) <= h*0.001f && MathF.Abs(c.Z) <= h*0.001f && MathF.Abs(d.Z) <= h*0.001f
