            if (plate && normal.Z < -0.99f) plateContact++;
            if (MathF.Min(a.Z,MathF.Min(c.Z,d.Z)) < -h*0.001f) belowPlate++;
            if (!plate && normal.Z <= -MathF.Cos(MathF.PI / 4)) unsupported++;
