        using Mesh mesh = Mesh.mshFromStlFile(input, Mesh.EStlUnit.MM, libSet: lib);
        if (mesh.nTriangleCount() == 0) throw new InvalidDataException("Empty mesh.");
        for (int i=0; i<mesh.nTriangleCount(); i++)
