            new BBox3(bounds.vecMin-pad, bounds.vecMax+pad));
        using Mesh phaseMesh = new(phase);
        using Voxels distance = new(phaseMesh);
        using Voxels inner = new(distance);
        using Voxels outer = new(distance);
