        float bottom = bounds.vecMin.Z-pad.Z-(bounds.vecMin.Z+bounds.vecMax.Z)/2;
        if (warp==1 && 1+0.03f*bottom <= 0) throw new ArgumentException("Graded period becomes nonpositive in render bounds.");
