            edgeDirections[key] = edgeDirections.GetValueOrDefault(key) + (forward ? 1 : -1);
        }
        for (int i = 0; i < mesh.nTriangleCount(); i++)
        {
            mesh.GetTriangle(i, out Vector3 a, out Vector3 c, out Vector3 d);
