        var queue = new Queue<int>();
        (int x,int y,int z) Decode(int i) => (i % nx, (i / nx) % ny, i / (nx * ny));
        IEnumerable<int> Neighbours(int i)
        {
            var (x,y,z) = Decode(i);
            if (x > 0) yield return i-1; if (x+1 < nx) yield return i+1;
