            if (!solid[i] && !visited[i] && (x==0 || y==0 || z==0 || x==nx-1 || y==ny-1 || z==nz-1)) Flood(i, false);
        }
        int trapped = 0, pockets = 0;
        for (int i = 0; i < solid.Length; i++) if (!solid[i] && !visited[i]) { pockets++; trapped += Flood(i, false); }
        Array.Clear(visited);
