        var edgeDirections = new Dictionary<(Vector3, Vector3), int>();
        static int Compare(Vector3 a, Vector3 c) => a.X != c.X ? a.X.CompareTo(c.X) : a.Y != c.Y ? a.Y.CompareTo(c.Y) : a.Z.CompareTo(c.Z);
